/**
 * Dual-language layout audit on live-generated specs (zh primary + en gloss).
 *
 * Fixtures: scripts/audit_bilingual_layout_live.py → tmp/bilingual_audit/*.json
 * (real PG topics regenerated by the real LLM). Skips when that directory is absent.
 *
 * jsdom has no text layout, so text width uses the script-aware em fallback for
 * both the loaders and the paint model below. Each node's painted box is the
 * primary label plus the gloss at 0.75em / line-height 1.2, wrapped in the same
 * column the node component passes to InlineEditableText. The audit then feeds
 * those painted sizes to the type's own relayout and checks:
 *   - every labelled node received its gloss
 *   - fixed-size nodes (circles, capsules, mind-map estimates) contain the paint
 *   - no two painted boxes overlap
 */
import { createPinia, setActivePinia } from 'pinia'

import { existsSync, readFileSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import { BILINGUAL_SECONDARY_LINE_HEIGHT, secondaryFontSize } from '@/diagramBilingual/measure'
import { useDiagramStore } from '@/stores/diagram'
import { recalculateMindMapV2ColumnPositions } from '@/stores/diagram/mindMapLayout'
import {
  recalculateBraceMapLayout,
  recalculateBridgeMapLayout,
  recalculateBubbleMapLayout,
  recalculateCircleMapLayout,
  recalculateFlowMapLayout,
  recalculateMultiFlowMapLayout,
  recalculateTreeMapLayout,
} from '@/stores/specLoader'
import { recalculateDoubleBubbleMapLayout } from '@/stores/specLoader/doubleBubbleMapMeasuredLayout'
import { estimateTextWidthFallbackPx } from '@/stores/specLoader/textMeasurementFallback'
import { useUIStore } from '@/stores/ui'
import type { Connection, DiagramNode, DiagramType } from '@/types'
import { mindMapBranchPaintBox } from '@/utils/mindMapBranchPaintBox'
import {
  MIND_MAP_TEXT_LINE_HEIGHT,
  resolveMindMapBranchBodyMaxWidthPx,
  resolveThinkingMapDisplayMaxWidthPx,
  wrapMindMapTextLines,
} from '@/utils/mindMapTextWrap'

/**
 * Stand-in browser layout for measure elements: width from the script-aware em
 * estimate, wrapping at `max-width` with CJK break rules, height from line count.
 */
function px(value: string): number {
  const parsed = Number.parseFloat(value)
  return Number.isFinite(parsed) ? parsed : 0
}

function simulatedBox(el: HTMLElement): Size {
  const style = el.style
  const fontSize = px(style.fontSize)
  const text = (el.textContent ?? '').trim()
  if (!fontSize || !text) return { width: 0, height: 0 }
  const bold = style.fontWeight === 'bold' || Number(style.fontWeight) >= 600
  const padX = px(style.paddingLeft) + px(style.paddingRight)
  const padY = px(style.paddingTop) + px(style.paddingBottom)
  const lineHeight = (px(style.lineHeight) || 1.4) * fontSize
  const single = estimateTextWidthFallbackPx(text, fontSize, { isTopic: bold })
  const maxWidth = px(style.maxWidth)
  if (style.whiteSpace === 'nowrap' || !maxWidth || single <= maxWidth) {
    return { width: Math.ceil(single + padX), height: Math.ceil(lineHeight + padY) }
  }
  const lines = wrapMindMapTextLines(text, maxWidth, {
    fontSize,
    fontWeight: bold ? 'bold' : 'normal',
  })
  let widest = 0
  for (const line of lines) {
    widest = Math.max(widest, estimateTextWidthFallbackPx(line, fontSize, { isTopic: bold }))
  }
  return {
    width: Math.ceil(Math.min(widest, maxWidth) + padX),
    height: Math.ceil(lines.length * lineHeight + padY),
  }
}

function installSimulatedLayout(): void {
  Object.defineProperty(HTMLElement.prototype, 'offsetWidth', {
    configurable: true,
    get(this: HTMLElement) {
      return simulatedBox(this).width
    },
  })
  Object.defineProperty(HTMLElement.prototype, 'offsetHeight', {
    configurable: true,
    get(this: HTMLElement) {
      return simulatedBox(this).height
    },
  })
}

const FIXTURE_DIR = resolve(__dirname, '../../tmp/bilingual_audit')
const FILES = existsSync(FIXTURE_DIR)
  ? readdirSync(FIXTURE_DIR).filter((name) => name.endsWith('.json'))
  : []

/** Generic thinking-map label cap (BRANCH / BRACE / context columns are ~200px). */
const THINKING_MAP_CAP = 200
const BOX_PAD_X = 28
const BOX_PAD_Y = 18
const OVERLAP_TOLERANCE = 2
const FIT_TOLERANCE = 2

type Fixture = { name: string; diagram_type: string; spec: Record<string, unknown> }
type Size = { width: number; height: number }
type Finding = { kind: 'gloss' | 'fit' | 'overlap'; detail: string }

function loadFixture(name: string): Fixture {
  return JSON.parse(readFileSync(resolve(FIXTURE_DIR, name), 'utf8')) as Fixture
}

function stubBrowser(): void {
  vi.stubGlobal('localStorage', {
    getItem: vi.fn(() => null),
    setItem: vi.fn(),
    removeItem: vi.fn(),
    clear: vi.fn(),
    length: 0,
    key: vi.fn(() => null),
  })
  vi.stubGlobal(
    'matchMedia',
    vi.fn(() => ({
      matches: false,
      media: '',
      onchange: null,
      addListener: vi.fn(),
      addEventListener: vi.fn(),
      removeListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    }))
  )
}

function textWidth(text: string, fontSize: number, bold = false): number {
  return estimateTextWidthFallbackPx(text, fontSize, { isTopic: bold })
}

/** Lines + widest line for one label wrapped at `column` (CJK break rules). */
function wrapBlock(text: string, fontSize: number, column: number, bold = false) {
  const label = text.trim()
  if (!label) return { width: 0, lines: 0 }
  const single = textWidth(label, fontSize, bold)
  if (single <= column) return { width: single, lines: 1 }
  const lines = wrapMindMapTextLines(label, column, {
    fontSize,
    fontWeight: bold ? 'bold' : 'normal',
  })
  return { width: column, lines: Math.max(1, lines.length) }
}

/** Primary + gloss content block in one column (InlineEditableText bilingual stack). */
function contentBlock(
  node: DiagramNode,
  fontSize: number,
  column: number,
  wrap = true,
  bold = false
) {
  const primary = node.text ?? ''
  const gloss = node.textSecondary ?? ''
  const glossFs = secondaryFontSize(fontSize)
  const p = wrap
    ? wrapBlock(primary, fontSize, column, bold)
    : { width: textWidth(primary, fontSize, bold), lines: primary.trim() ? 1 : 0 }
  const g = wrap
    ? wrapBlock(gloss, glossFs, column)
    : { width: textWidth(gloss, glossFs), lines: gloss.trim() ? 1 : 0 }
  return {
    width: Math.max(p.width, g.width),
    height:
      p.lines * fontSize * MIND_MAP_TEXT_LINE_HEIGHT +
      g.lines * glossFs * BILINGUAL_SECONDARY_LINE_HEIGHT,
  }
}

function fontSizeOf(node: DiagramNode, fallback: number): number {
  const raw = node.style?.fontSize
  const parsed = typeof raw === 'number' ? raw : Number.parseFloat(String(raw ?? ''))
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback
}

function isTopicLike(node: DiagramNode): boolean {
  return node.type === 'topic' || node.type === 'center' || node.id === 'topic'
}

function isCircleType(type: string): boolean {
  return type === 'circle_map' || type === 'bubble_map' || type === 'double_bubble_map'
}

function circleDiameter(node: DiagramNode): number | null {
  const size = node.style?.size
  return typeof size === 'number' && size > 0 ? size : null
}

/** Painted box for a box-shaped thinking-map node. */
function paintedBox(node: DiagramNode): Size {
  const topic = isTopicLike(node)
  const fontSize = fontSizeOf(node, topic ? 18 : 14)
  const fixedWidth = typeof node.style?.width === 'number' ? node.style.width : null
  let column = resolveThinkingMapDisplayMaxWidthPx(node.text ?? '', fontSize, THINKING_MAP_CAP, {
    fontWeight: topic ? 'bold' : 'normal',
  })
  if (fixedWidth) column = Math.min(column, fixedWidth - BOX_PAD_X)
  const block = contentBlock(node, fontSize, column, true, topic)
  return {
    width: fixedWidth ?? block.width + BOX_PAD_X,
    height: block.height + BOX_PAD_Y,
  }
}

/** Circle text column, matching CircleNode.textMaxWidth. */
function circleColumn(node: DiagramNode, type: string, fontSize: number): number {
  if (isTopicLike(node)) {
    return resolveThinkingMapDisplayMaxWidthPx(node.text ?? '', fontSize, 300, {
      fontWeight: 'bold',
    })
  }
  const cap = type === 'bubble_map' ? 200 : 140
  return resolveThinkingMapDisplayMaxWidthPx(node.text ?? '', fontSize, cap) + 16
}

function glossFindings(nodes: DiagramNode[]): Finding[] {
  return nodes
    .filter(
      (n) => n.type !== 'boundary' && (n.text ?? '').trim() && !(n.textSecondary ?? '').trim()
    )
    .map((n) => ({ kind: 'gloss' as const, detail: `${n.id} "${n.text}" has no gloss` }))
}

function circleFitFindings(nodes: DiagramNode[], type: string): Finding[] {
  const out: Finding[] = []
  for (const node of nodes) {
    if (node.type === 'boundary' || !(node.textSecondary ?? '').trim()) continue
    const topic = isTopicLike(node)
    const fontSize = fontSizeOf(node, topic ? 18 : 16)
    const capsuleW = typeof node.style?.width === 'number' ? node.style.width : null
    const capsuleH = typeof node.style?.height === 'number' ? node.style.height : null
    const noWrap = node.style?.noWrap === true || type === 'double_bubble_map'
    const diameter = circleDiameter(node)
    if (capsuleW && capsuleH && type === 'double_bubble_map') {
      const block = contentBlock(node, fontSize, capsuleW, !noWrap, topic)
      if (block.width > capsuleW - 8 + FIT_TOLERANCE || block.height > capsuleH + FIT_TOLERANCE) {
        out.push({
          kind: 'fit',
          detail: `${node.id} "${node.text}/${node.textSecondary}" capsule ${capsuleW}x${capsuleH} < text ${Math.ceil(block.width)}x${Math.ceil(block.height)}`,
        })
      }
      continue
    }
    if (!diameter) continue
    const column = noWrap ? Number.POSITIVE_INFINITY : circleColumn(node, type, fontSize)
    const block = contentBlock(node, fontSize, column, !noWrap, topic)
    const diagonal = Math.hypot(block.width, block.height)
    if (diagonal > diameter + FIT_TOLERANCE) {
      out.push({
        kind: 'fit',
        detail: `${node.id} "${node.text}/${node.textSecondary}" circle ${diameter} < text diagonal ${Math.ceil(diagonal)} (${Math.ceil(block.width)}x${Math.ceil(block.height)})`,
      })
    }
  }
  return out
}

type Shape = {
  id: string
  label: string
  x: number
  y: number
  w: number
  h: number
  circle: boolean
}

function overlapFindings(shapes: Shape[]): Finding[] {
  const out: Finding[] = []
  for (let i = 0; i < shapes.length; i++) {
    for (let j = i + 1; j < shapes.length; j++) {
      const a = shapes[i]
      const b = shapes[j]
      if (!a || !b) continue
      let hit: boolean
      if (a.circle && b.circle) {
        const dist = Math.hypot(a.x + a.w / 2 - (b.x + b.w / 2), a.y + a.h / 2 - (b.y + b.h / 2))
        hit = dist + OVERLAP_TOLERANCE < (a.w + b.w) / 2
      } else {
        const ox = Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)
        const oy = Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y)
        hit = ox > OVERLAP_TOLERANCE && oy > OVERLAP_TOLERANCE
      }
      if (hit) {
        out.push({ kind: 'overlap', detail: `"${a.label}" × "${b.label}"` })
      }
    }
  }
  return out
}

function toShapes(nodes: DiagramNode[], dims: Record<string, Size>, circles: boolean): Shape[] {
  return nodes
    .filter((n) => n.type !== 'boundary' && n.position && dims[n.id])
    .map((n) => {
      const d = dims[n.id] as Size
      return {
        id: n.id,
        label: `${n.text ?? ''}/${n.textSecondary ?? ''}`.slice(0, 48),
        x: n.position?.x ?? 0,
        y: n.position?.y ?? 0,
        w: d.width,
        h: d.height,
        circle: circles && circleDiameter(n) != null && !(typeof n.style?.width === 'number'),
      }
    })
}

function auditMindMap(
  nodes: DiagramNode[],
  connections: Connection[],
  styleId?: string
): Finding[] {
  const findings: Finding[] = []
  const widths: Record<string, number> = {}
  const heights: Record<string, number> = {}
  const painted: Record<string, Size> = {}
  for (const node of nodes) {
    if (node.type === 'boundary') continue
    if (node.id === 'topic') {
      const fontSize = 18
      const block = contentBlock(node, fontSize, 300, true, true)
      painted[node.id] = { width: block.width + 32, height: block.height + 20 }
      continue
    }
    const box = mindMapBranchPaintBox(node, connections, styleId)
    const column = resolveMindMapBranchBodyMaxWidthPx(node.text ?? '', '', box.fontSize)
    const block = contentBlock(node, box.fontSize, column)
    const padX = box.shape === 'underline' ? 16 : 32
    const padY = box.shape === 'underline' ? 9 : 20
    painted[node.id] = { width: block.width + padX, height: block.height + padY }
    const est = {
      width: Number(node.data?.estimatedWidth ?? 0),
      height: Number(node.data?.estimatedHeight ?? 0),
    }
    const p = painted[node.id] as Size
    if (p.width > est.width + FIT_TOLERANCE + 4) {
      findings.push({
        kind: 'fit',
        detail: `${node.id} "${node.text}/${node.textSecondary}" width est ${est.width} < painted ${Math.ceil(p.width)}`,
      })
    }
  }
  for (const [id, size] of Object.entries(painted)) {
    widths[id] = size.width
    heights[id] = size.height
  }
  const laid = recalculateMindMapV2ColumnPositions(
    nodes,
    painted.topic?.width ?? null,
    widths,
    heights,
    connections,
    new Set(),
    styleId
  ).nodes
  const boxes: Record<string, Size> = {}
  for (const node of laid) {
    const p = painted[node.id]
    if (!p) continue
    boxes[node.id] = {
      width: p.width,
      height: Math.max(p.height, Number(node.data?.estimatedHeight ?? 0)),
    }
  }
  return [...findings, ...overlapFindings(toShapes(laid, boxes, false))]
}

function relayout(
  type: string,
  nodes: DiagramNode[],
  connections: Connection[],
  dims: Record<string, Size>
) {
  switch (type) {
    case 'circle_map':
      return recalculateCircleMapLayout(nodes, dims)
    case 'bubble_map':
      return recalculateBubbleMapLayout(nodes, dims)
    case 'double_bubble_map':
      return recalculateDoubleBubbleMapLayout(nodes, dims)
    case 'tree_map':
      return recalculateTreeMapLayout(nodes, dims)
    case 'flow_map':
      return recalculateFlowMapLayout(nodes, dims)
    case 'multi_flow_map':
      return recalculateMultiFlowMapLayout(nodes, null, dims)
    case 'brace_map':
      return recalculateBraceMapLayout(nodes, connections, dims)
    case 'bridge_map':
      return recalculateBridgeMapLayout(nodes, dims)
    default:
      return nodes
  }
}

function auditThinkingMap(
  type: string,
  nodes: DiagramNode[],
  connections: Connection[]
): Finding[] {
  const circles = isCircleType(type)
  const dims: Record<string, Size> = {}
  for (const node of nodes) {
    if (node.type === 'boundary') continue
    const d = circleDiameter(node)
    if (circles && d && typeof node.style?.width !== 'number')
      dims[node.id] = { width: d, height: d }
    else if (circles && typeof node.style?.width === 'number')
      dims[node.id] = {
        width: node.style.width,
        height: Number(node.style.height ?? node.style.width),
      }
    else dims[node.id] = paintedBox(node)
  }
  const laid = relayout(type, nodes, connections, dims)
  const laidDims: Record<string, Size> = {}
  for (const node of laid) {
    const d = circleDiameter(node)
    if (circles && d && typeof node.style?.width !== 'number')
      laidDims[node.id] = { width: d, height: d }
    else if (dims[node.id]) laidDims[node.id] = dims[node.id] as Size
  }
  const fit = circles ? circleFitFindings(laid, type) : []
  return [...fit, ...overlapFindings(toShapes(laid, laidDims, circles))]
}

function auditFixture(fixture: Fixture): Finding[] {
  const store = useDiagramStore()
  const type = (
    fixture.diagram_type === 'mind_map' ? 'mindmap' : fixture.diagram_type
  ) as DiagramType
  store.loadFromSpec(fixture.spec, type)
  const nodes = (store.data?.nodes ?? []).map((n) => ({ ...n }))
  const connections = store.data?.connections ?? []
  const findings = glossFindings(nodes)
  if (type === 'mindmap') {
    const styleId = store.data?._mindmap_diagram_style as string | undefined
    return [...findings, ...auditMindMap(nodes, connections, styleId)]
  }
  return [...findings, ...auditThinkingMap(type, nodes, connections)]
}

describe.skipIf(FILES.length === 0)('bilingual layout audit (live generated)', () => {
  beforeEach(() => {
    setActivePinia(createPinia())
    stubBrowser()
    installSimulatedLayout()
    useUIStore().mindMapCanvasMode = 'v2'
  })

  it.each(FILES)('%s', (file) => {
    const findings = auditFixture(loadFixture(file))
    if (findings.length) {
      console.log(`${file}\n${findings.map((f) => `  [${f.kind}] ${f.detail}`).join('\n')}`)
    }
    expect(findings).toEqual([])
  })
})
